  compositions:`<section class="panel spaced"><div class="section-heading"><h2>Environment compositions</h2><div class="actions">${button('assemble_environment','Assemble active work')}${button('plan_composition','Plan composition')}</div></div><p class="planning-note">Assemble active work creates disposable generated branches from the latest captured revisions, builds every selected application and updates the configured DEV/TEST GitOps targets. Conflicts pause the operation for an agent.</p>${compositionView(productItems('compositions'))}</section>`,
  providers:`${typeof externalProductPanels==='function'?externalProductPanels():'<section class="panel"><p class="muted">Provider settings are unavailable until the provider module loads.</p></section>'}`,
  releases:`${typeof flowProductPanel==='function'?flowProductPanel():''}<section class="panel"><div class="section-heading"><h2>Release history & intent</h2>${button('plan_release','Plan release')}</div><p class="muted">Plans are immutable intent. External MCP releases are recorded with their environment and evidence.</p>${productItems('releases').map(r=>`<div data-live-key="release-${esc(r.id)}" class="row"><div class="row-heading"><h3>${esc(r.name)}</h3>${badge(r.status)}</div><dl>${detail('Environment',r.environment_id)}${detail('Included integrations',r.integration_ids)}${detail('Excluded active work',r.excluded_integration_ids)}${detail('Source commits',r.source_commits)}${detail('GitOps commits',r.gitops_commits)}${detail('Evidence',r.evidence)}${detail('Notes',r.notes)}</dl><span class="meta">${esc(r.recorded_externally?'External release recorded':'Release intent')} · ${esc(r.actor)} · ${esc(date(r.created_at))}</span></div>`).join('')||'<p class="muted">No release records.</p>'}</section>`,
