 handoff:{label:'Create structured handoff',fields:[...memoryBase,field('completed','Completed work','lines'),field('current','Current work','textarea'),field('remaining','Remaining work','lines'),field('next','Next actions','lines'),field('warnings','Warnings / do not change','lines')]},
 resolve_blocker:{label:'Resolve blocker',fields:[field('body','Resolution','textarea',true)]},
 create_gate:{label:'Create verification gate',fields:[title(),field('reason','Reason for this gate','textarea',true),field('integration_ids','Integrations covered','integrations',true),field('position','Plan position','number'),field('blocking','Blocks integration readiness','boolean'),field('environment_id','Environment','environment'),field('commit','Planned commit'),field('deployment','Planned deployment')]},
 add_check:{label:'Add verification check',fields:[title(),field('mechanism','Execution mechanism','select',true,['unit','integration','e2e','browser','manual','regression','migration','smoke','custom']),field('instructions','Instructions','textarea')]},
 record_check_result:{label:'Record check result',help:'Record the actual tested commit or deployment. Each execution is preserved; reruns never overwrite earlier evidence.',fields:[field('result','Result','select',true,['passed','failed','blocked','skipped']),field('commit','Tested commit'),field('deployment','Tested deployment'),field('environment_id','Environment','environment'),field('steps','Steps performed','lines'),field('observations','Observations','textarea'),field('logs','Logs','textarea'),field('artifacts','Artifacts','artifacts')]},
 record_finding:{label:'Create finding',fields:[title(),field('severity','Severity','select',true,['minor','major','critical']),field('body','What failed?','textarea',true),field('integration_ids','Blocked integrations','integrations'),field('gate_ids','Blocked gates','gates'),field('blocks_release','Blocks release readiness','boolean')]},
