function applicationView(xs) {
 return xs.map(a=>`<article data-live-key="component-${esc(a.id)}" class="row"><h3>${esc(a.name)}</h3><dl>${detail('Kind',a.kind||'APPLICATION')}${detail('Repository',repositoryName(a.repository_id))}${detail('Path',a.path||'/')}</dl>${typeof externalApplicationActions==='function'?externalApplicationActions(a):''}<span class="meta">${esc(a.id)}</span></article>`).join('')||'<p class="muted">No components yet. Define applications for environments or libraries for package publication.</p>';
}
function repositoryName(id){const r=list(state.repositories).find(x=>x.id===id);return r?`${r.name} (${r.id})`:id;}
function revisionLabel(r){const i=list(state.integrations).find(x=>x.id===r.integration_id),f=list(state.features).find(x=>x.id===r.feature_id||x.id===i?.feature_id);return `${f?.title||r.feature_id} / ${i?.title||r.integration_id} · ${r.head_commit}`;}
function revisionView(integrationID){
 const revisions=list(state.integration_revisions).filter(r=>r.integration_id===integrationID);
 return `<details><summary>Immutable revisions (${revisions.length})</summary>${revisions.map(r=>`<article class="row"><p class="revision-label">${esc(r.id)}</p><dl>${detail('Repository',repositoryName(r.repository_id))}${detail('Branch',r.branch)}${detail('Base commit',r.base_commit)}${detail('Head commit',r.head_commit)}${detail('Included commits',r.commits)}</dl><span class="meta">${esc(r.actor)} · ${esc(date(r.created_at))}</span></article>`).join('')||'<p class="muted">No immutable revisions recorded. Record exact code before planning a composition.</p>'}</details>`;
}

function compositionView(xs){
 return xs.slice().reverse().map(c=>{
 const target=c.environment_snapshot||{},isDesired=productItems('environments').some(e=>e.desired_composition_id===c.id);
 return `<article data-live-key="composition-${esc(c.id)}" class="row"><div class="row-heading"><div><h3>${esc(c.name)}</h3><span class="meta">${esc(c.id)} · ${esc(c.actor)} · ${esc(date(c.created_at))}</span></div><span class="tag">${typeof flowCompositionStatus==='function'?esc(flowCompositionStatus(c)):'Planned / not deployed'}</span></div><p>Target: <strong>${esc(target.name||c.environment_id)}</strong> · ${esc(target.cluster||'cluster unspecified')} / ${esc(target.namespace||'namespace unspecified')}</p>${typeof flowCompositionActions==='function'?flowCompositionActions(c):''}${isDesired?'<p class="planning-note">Selected as desired. Reconciled and runtime state remain separate observations.</p>':button('select_composition','Set desired',{id:c.id})}${list(c.components).map(component=>{const app=list(c.application_snapshots).find(a=>a.id===component.application_id);return `<div class="snapshot"><h3>${esc(app?.name||component.application_id)}</h3><dl>${detail('Application / repository / path',`${component.application_id} · ${app?.repository_id||''} · ${app?.path||'/'}`)}${detail('Base reference',component.base_ref)}${detail('Pinned base commit',component.base_commit)}${detail('Generated target branch',component.target_branch)}</dl>${list(component.revision_ids).map(id=>{const r=list(c.revision_snapshots).find(x=>x.id===id);return r?`<details><summary>${esc(r.integration_id)} · ${esc(r.head_commit)}</summary><dl>${detail('Captured revision',r.id)}${detail('Source branch',r.branch)}${detail('Source base',r.base_commit)}${detail('Source head',r.head_commit)}${detail('Ordered source commits',r.commits)}</dl><span class="meta">${esc(r.actor)} · ${esc(date(r.created_at))}</span></details>`:`<p class="revision-label">${esc(id)}</p>`;}).join('')||'<p class="muted">Base-only application: no integration revisions selected.</p>'}</div>`}).join('')}<details><summary>Exact immutable snapshots</summary><pre>${esc(JSON.stringify({environment:c.environment_snapshot,applications:c.application_snapshots,revisions:c.revision_snapshots,components:c.components},null,2))}</pre></details></article>`;
 }).join('')||'<p class="muted">No compositions planned. Capture integration revisions, then choose which exact work belongs in each application and environment.</p>';
}
let compositionRowSequence=0;
function addCompositionRow(){
 const index=++compositionRowSequence,id=`composition-${index}`,row=document.createElement('fieldset');row.className='application-row';
 row.innerHTML=`<legend>Component row ${index}</legend><div class="field"><label for="${id}-application">Component *</label><select id="${id}-application" data-component-field="application_id" required><option value="">Choose a component</option>${productItems('applications').filter(a=>a.kind!=='LIBRARY').map(a=>`<option value="${esc(a.id)}">${esc(a.name)} · ${esc(repositoryName(a.repository_id))}</option>`).join('')}</select></div><p class="meta" data-repository-note>Select a component to see its repository revisions.</p><div class="form-grid"><div class="field"><label for="${id}-base-ref">Base reference *</label><input id="${id}-base-ref" data-component-field="base_ref" value="main" required></div><div class="field"><label for="${id}-target">Generated target branch *</label><input id="${id}-target" data-component-field="target_branch" placeholder="generated/dev" pattern="generated/.+" required></div></div><div class="field"><label for="${id}-base">Pinned base commit (full SHA) *</label><input id="${id}-base" data-component-field="base_commit" pattern="([a-f0-9]{40}|[a-f0-9]{64})" required></div><div class="field"><label for="${id}-revisions">Integration revisions, in composition order</label><select id="${id}-revisions" data-component-field="revision_ids" multiple size="5"></select><span class="hint">Command / Control + click to select several. Select none for base-only code. Source revisions are client-reported until a Git adapter verifies them.</span></div><div class="actions"><button type="button" data-move="up">Move selected up</button><button type="button" data-move="down">Move selected down</button><button type="button" data-remove-row>Remove application row</button></div>`;
 row.querySelector('[data-component-field="application_id"]').onchange=e=>{
 const app=productItems('applications').find(a=>a.id===e.target.value),select=row.querySelector('[data-component-field="revision_ids"]');
 select.innerHTML=list(state.integration_revisions).filter(r=>r.product_id===productID&&r.repository_id===app?.repository_id&&(currentForm?.action!=='prepare_release_candidate'||['ready','released'].includes(list(state.integrations).find(i=>i.id===r.integration_id)?.status))).map(r=>`<option value="${esc(r.id)}">${esc(revisionLabel(r))}</option>`).join('');
 row.querySelector('[data-repository-note]').textContent=app?`${repositoryName(app.repository_id)} · Path ${app.path||'/'} · ${select.options.length} captured revisions available`:'Select a component to see its repository revisions.';
 };
 row.querySelector('[data-remove-row]').onclick=()=>row.remove();
 for(const direction of ['up','down'])row.querySelector(`[data-move="${direction}"]`).onclick=()=>{
 const select=row.querySelector('[data-component-field="revision_ids"]'),options=Array.from(select.options);if(direction==='down')options.reverse();
 for(const option of options){const sibling=direction==='up'?option.previousElementSibling:option.nextElementSibling;if(option.selected&&sibling&&!sibling.selected){if(direction==='up')select.insertBefore(option,sibling);else select.insertBefore(sibling,option);}}
 };
 $('#composition-rows').append(row);
}
function readCompositionRows(form){
 const components=Array.from(form.querySelectorAll('.application-row')).map(row=>{
 const value=name=>row.querySelector(`[data-component-field="${name}"]`).value.trim();
 return {application_id:value('application_id'),base_ref:value('base_ref'),base_commit:value('base_commit'),target_branch:value('target_branch'),revision_ids:Array.from(row.querySelector('[data-component-field="revision_ids"]').selectedOptions).map(o=>o.value)};
 });
 if(!components.length)throw new Error('Add at least one application row.');
 if(new Set(components.map(c=>c.application_id)).size!==components.length)throw new Error('Each application can appear only once.');
 for(const c of components){if(!c.application_id||!c.base_ref)throw new Error('Every application row needs an application and base reference.');if(!/^(?:[a-f0-9]{40}|[a-f0-9]{64})$/.test(c.base_commit))throw new Error('Each pinned base commit must be a full lowercase 40- or 64-character SHA.');if(!c.target_branch.startsWith('generated/'))throw new Error('Target branches must begin with generated/.');}
 return components;
}
